# تلوين أزرار Telegram فعلياً عبر MTProto KeyboardButtonStyle.
# لا توجد أي Custom Emoji هنا. الألوان: primary=أزرق، success=أخضر، danger=أحمر.
try:
    _OriginalInlineKeyboardButton = InlineKeyboardButton
except NameError:
    _OriginalInlineKeyboardButton = None

try:
    from pyrogram import raw as _pyro_raw
except Exception:
    _pyro_raw = None

try:
    from pyrogram.raw.core import TLObject as _TLObject
    from pyrogram.raw.core.primitives import Int as _TLInt, String as _TLString, Bytes as _TLBytes
except Exception:
    _TLObject = object
    _TLInt = _TLString = _TLBytes = None

try:
    from pyrogram.types import KeyboardButtonStyle as _KeyboardButtonStyle
except Exception:
    try:
        from pyrogram.raw.types import KeyboardButtonStyle as _KeyboardButtonStyle
    except Exception:
        _KeyboardButtonStyle = None

try:
    from pyrogram.enums import ButtonStyle as _ButtonStyle
except Exception:
    _ButtonStyle = None

_COLOR_INDEX = 0

# Telegram current MTProto constructors (verified against the current schema):
# KeyboardButtonStyle = 0x4FDD3430
# keyboardButtonCallback = 0xE62BC960
# keyboardButtonUrl = 0xD80C25EC
# keyboardButtonSwitchInline = 0x991399FC
# keyboardButtonGame = 0x89C590F9
# keyboardButtonWebView = 0xE846B1A0

class _CompatKeyboardButtonStyle(_TLObject):
    ID = 0x4FDD3430
    QUALNAME = 'types.KeyboardButtonStyle'
    def __init__(self, style):
        self.style = style
    def write(self, *args):
        if _TLInt is None:
            raise RuntimeError('Pyrogram raw primitives unavailable')
        flags = {'primary': 1 << 0, 'danger': 1 << 1, 'success': 1 << 2}.get(self.style, 0)
        return _TLInt(self.ID, False) + _TLInt(flags, False)

class _CompatKeyboardButtonCallback(_TLObject):
    ID = 0xE62BC960
    QUALNAME = 'types.KeyboardButtonCallback'
    def __init__(self, text, data, style):
        self.text=text; self.data=data; self.style=style
    def write(self, *args):
        if _TLInt is None:
            raise RuntimeError('Pyrogram raw primitives unavailable')
        flags = 1 << 10
        return (_TLInt(self.ID, False) + _TLInt(flags, False) +
                self.style.write() + _TLString(self.text) + _TLBytes(self.data))

class _CompatKeyboardButtonUrl(_TLObject):
    ID = 0xD80C25EC
    QUALNAME = 'types.KeyboardButtonUrl'
    def __init__(self, text, url, style):
        self.text=text; self.url=url; self.style=style
    def write(self, *args):
        if _TLInt is None:
            raise RuntimeError('Pyrogram raw primitives unavailable')
        flags = 1 << 10
        return (_TLInt(self.ID, False) + _TLInt(flags, False) +
                self.style.write() + _TLString(self.text) + _TLString(self.url))

class _CompatKeyboardButtonSwitchInline(_TLObject):
    ID = 0x991399FC
    QUALNAME = 'types.KeyboardButtonSwitchInline'
    def __init__(self, text, query, style, same_peer=False):
        self.text=text; self.query=query; self.style=style; self.same_peer=same_peer
    def write(self, *args):
        if _TLInt is None:
            raise RuntimeError('Pyrogram raw primitives unavailable')
        flags = (1 << 0 if self.same_peer else 0) | (1 << 10)
        return (_TLInt(self.ID, False) + _TLInt(flags, False) +
                self.style.write() + _TLString(self.text) + _TLString(self.query))

class _CompatKeyboardButtonGame(_TLObject):
    ID = 0x89C590F9
    QUALNAME = 'types.KeyboardButtonGame'
    def __init__(self, text, style):
        self.text=text; self.style=style
    def write(self, *args):
        if _TLInt is None:
            raise RuntimeError('Pyrogram raw primitives unavailable')
        flags = 1 << 10
        return _TLInt(self.ID, False) + _TLInt(flags, False) + self.style.write() + _TLString(self.text)

class _CompatKeyboardButtonWebView(_TLObject):
    ID = 0xE846B1A0
    QUALNAME = 'types.KeyboardButtonWebView'
    def __init__(self, text, url, style):
        self.text=text; self.url=url; self.style=style
    def write(self, *args):
        if _TLInt is None:
            raise RuntimeError('Pyrogram raw primitives unavailable')
        flags = 1 << 10
        return (_TLInt(self.ID, False) + _TLInt(flags, False) +
                self.style.write() + _TLString(self.text) + _TLString(self.url))

def _make_button_style(style):
    if style not in ('danger', 'success', 'primary'):
        return None
    if _KeyboardButtonStyle is not None:
        try:
            if style == 'danger': return _KeyboardButtonStyle(bg_danger=True)
            if style == 'success': return _KeyboardButtonStyle(bg_success=True)
            if style == 'primary': return _KeyboardButtonStyle(bg_primary=True)
        except Exception:
            pass
    if _ButtonStyle is not None:
        try:
            return getattr(_ButtonStyle, style.upper())
        except Exception:
            pass
    # مهم: لا نرجع string. إذا كانت مكتبة Pyrogram قديمة، نستخدم TL compat أدناه.
    return None

def _compat_style(style):
    return _CompatKeyboardButtonStyle(style)

def _button_style_for(text, callback_data=None, url=None, requested=None):
    global _COLOR_INDEX
    label = str(text or '')
    data = str(callback_data or '')
    # اللون المطلوب صراحةً له الأولوية دائماً.
    if requested in ('danger', 'success', 'primary'):
        return requested
    # أزرار صفحات الأوامر تكون خضراء افتراضياً؛ الزر المحدد فقط
    # يتم تمرير color='danger' له من _command_nav_markup.
    if data.startswith('commands') or label in ('م1', 'م2', 'م3', 'الالعاب', 'التسليه', 'البنك', 'زواج'):
        return 'success'
    # زر القناة يبقى أزرق.
    if url:
        return 'primary'
    if any(x in label for x in ('حظر', 'طرد', 'كتم', 'مسح', 'حذف', 'منع', 'الغاء', 'إلغاء')):
        return 'danger'
    if any(x in label for x in ('تفعيل', 'فتح', 'إضافة', 'اضف', 'رفع', 'السماح', 'اشتراك')):
        return 'success'
    style = ('primary', 'success', 'danger')[_COLOR_INDEX % 3]
    _COLOR_INDEX += 1
    return style

class _StyledInlineKeyboardButton(_OriginalInlineKeyboardButton if _OriginalInlineKeyboardButton else object):
    def __init__(self, text, *args, **kwargs):
        self._telegram_button_style = kwargs.pop('_telegram_button_style', None)
        super().__init__(text, *args, **kwargs)

    async def write(self, client):
        style_name = self._telegram_button_style
        style_obj = _make_button_style(style_name)

        # أولاً: إذا كانت الاستضافة تحتوي raw schema حديث، استخدمه مباشرة.
        if _pyro_raw is not None and style_obj is not None:
            if self.callback_data is not None:
                data = bytes(self.callback_data, 'utf-8') if isinstance(self.callback_data, str) else self.callback_data
                try:
                    return _pyro_raw.types.KeyboardButtonCallback(text=self.text, data=data, style=style_obj)
                except (TypeError, AttributeError): pass
            if self.url is not None:
                try:
                    return _pyro_raw.types.KeyboardButtonUrl(text=self.text, url=self.url, style=style_obj)
                except (TypeError, AttributeError): pass
            if getattr(self, 'switch_inline_query', None) is not None:
                try:
                    return _pyro_raw.types.KeyboardButtonSwitchInline(text=self.text, query=self.switch_inline_query, style=style_obj)
                except (TypeError, AttributeError): pass
            if getattr(self, 'switch_inline_query_current_chat', None) is not None:
                try:
                    return _pyro_raw.types.KeyboardButtonSwitchInline(text=self.text, query=self.switch_inline_query_current_chat, same_peer=True, style=style_obj)
                except (TypeError, AttributeError): pass
            if getattr(self, 'callback_game', None) is not None:
                try:
                    return _pyro_raw.types.KeyboardButtonGame(text=self.text, style=style_obj)
                except (TypeError, AttributeError): pass
            if getattr(self, 'web_app', None) is not None:
                try:
                    return _pyro_raw.types.KeyboardButtonWebView(text=self.text, url=self.web_app.url, style=style_obj)
                except (TypeError, AttributeError): pass

        # ثانيًا: هذا المسار لا يعتمد على نسخة raw المثبتة؛ يرسل constructor
        # الجديد نفسه حتى لو كانت Pyrogram القديمة لا تعرف KeyboardButtonStyle.
        if style_name in ('danger', 'success', 'primary') and _TLInt is not None:
            style_compat = _compat_style(style_name)
            if self.callback_data is not None:
                data = bytes(self.callback_data, 'utf-8') if isinstance(self.callback_data, str) else self.callback_data
                return _CompatKeyboardButtonCallback(self.text, data, style_compat)
            if self.url is not None:
                return _CompatKeyboardButtonUrl(self.text, self.url, style_compat)
            if getattr(self, 'switch_inline_query', None) is not None:
                return _CompatKeyboardButtonSwitchInline(self.text, self.switch_inline_query, style_compat)
            if getattr(self, 'switch_inline_query_current_chat', None) is not None:
                return _CompatKeyboardButtonSwitchInline(self.text, self.switch_inline_query_current_chat, style_compat, same_peer=True)
            if getattr(self, 'callback_game', None) is not None:
                return _CompatKeyboardButtonGame(self.text, style_compat)
            if getattr(self, 'web_app', None) is not None:
                return _CompatKeyboardButtonWebView(self.text, self.web_app.url, style_compat)

        return await super().write(client)

def create_emoji_btn(text, callback=None, url=None, color=None, *args, **kwargs):
    # نفس اسم الدالة حتى لا نحتاج لتعديل بقية البوت، لكن بدون أي Custom Emoji.
    if callback is None and 'callback_data' in kwargs:
        callback = kwargs.pop('callback_data')
    if color is None and '_style' in kwargs:
        color = kwargs.pop('_style')
    style = _button_style_for(text, callback_data=callback, url=url, requested=color)
    if _OriginalInlineKeyboardButton is None:
        raise RuntimeError('InlineKeyboardButton is not available')
    return _StyledInlineKeyboardButton(
        text, *args, callback_data=callback, url=url,
        _telegram_button_style=style, **kwargs
    )

