class PostgresRedisClient:
    def __init__(self, dsn):
        import threading, queue
        self.dsn = dsn
        self._conn = None
        self._lock = threading.Lock()
        self._kv_cache = {}
        self._sets_cache = {}
        self._hashes_cache = {}
        self._zsets_cache = {}
        self._writer_queue = queue.Queue()
        self._init_db()
        self._preload_db()
        self._writer_thread = threading.Thread(target=self._writer_loop, daemon=True)
        self._writer_thread.start()
    def _get_conn(self):
        import psycopg2, re
        if getattr(self, "_conn", None) is None or self._conn.closed != 0:
            try:
                self._conn = psycopg2.connect(self.dsn, connect_timeout=4)
            except psycopg2.OperationalError:
                m = re.match(r'^postgresql://([^:]+):([^@]+)@db\.([a-zA-Z0-9_-]+)\.supabase\.co:?\d*/(.*)$', self.dsn)
                if m:
                    user, pwd, ref, dbname = m.groups()
                    pooler_user = f"{user}.{ref}" if "." not in user else user
                    regions = ['eu-central-1', 'eu-west-1', 'eu-west-2', 'us-east-1', 'us-west-1', 'ap-southeast-1', 'sa-east-1']
                    for idx, reg in enumerate(regions):
                        fallback_dsn = f"postgresql://{pooler_user}:{pwd}@aws-0-{reg}.pooler.supabase.com:6543/{dbname}"
                        try:
                            self._conn = psycopg2.connect(fallback_dsn, connect_timeout=4)
                            break
                        except Exception:
                            if idx == len(regions) - 1:
                                raise
                else:
                    raise
        return self._conn
    def _execute(self, sql, params=(), fetch=None):
        import psycopg2
        for attempt in range(2):
            try:
                conn = self._get_conn()
                with conn.cursor() as cur:
                    cur.execute(sql, params)
                    if fetch == "one":
                        res = cur.fetchone()
                    elif fetch == "all":
                        res = cur.fetchall()
                    elif fetch == "rowcount":
                        res = cur.rowcount
                    else:
                        res = None
                conn.commit()
                return res
            except psycopg2.OperationalError:
                if getattr(self, "_conn", None):
                    try:
                        self._conn.close()
                    except Exception:
                        pass
                self._conn = None
                if attempt == 1:
                    raise
            except Exception:
                if getattr(self, "_conn", None):
                    try:
                        self._conn.rollback()
                    except Exception:
                        pass
                raise
    def _init_db(self):
        self._execute("""
            CREATE TABLE IF NOT EXISTS redis_kv (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL,
                expires_at BIGINT NULL
            );
        """)
        self._execute("CREATE INDEX IF NOT EXISTS idx_redis_kv_expires ON redis_kv (expires_at);")
        self._execute("""
            CREATE TABLE IF NOT EXISTS redis_sets (
                key TEXT NOT NULL,
                member TEXT NOT NULL,
                PRIMARY KEY (key, member)
            );
        """)
        self._execute("""
            CREATE TABLE IF NOT EXISTS redis_hashes (
                key TEXT NOT NULL,
                field TEXT NOT NULL,
                value TEXT NOT NULL,
                PRIMARY KEY (key, field)
            );
        """)
        self._execute("""
            CREATE TABLE IF NOT EXISTS redis_zsets (
                key TEXT NOT NULL,
                member TEXT NOT NULL,
                score DOUBLE PRECISION NOT NULL,
                PRIMARY KEY (key, member)
            );
        """)
    def _preload_db(self):
        import time
        now = int(time.time())
        try:
            rows = self._execute("SELECT key, value, expires_at FROM redis_kv WHERE expires_at IS NULL OR expires_at > %s", (now,), fetch="all") or []
            with self._lock:
                for k, v, exp in rows:
                    self._kv_cache[k] = (v, exp)
            rows = self._execute("SELECT key, member FROM redis_sets", fetch="all") or []
            with self._lock:
                for k, m in rows:
                    if k not in self._sets_cache:
                        self._sets_cache[k] = set()
                    self._sets_cache[k].add(m)
            rows = self._execute("SELECT key, field, value FROM redis_hashes", fetch="all") or []
            with self._lock:
                for k, f, v in rows:
                    if k not in self._hashes_cache:
                        self._hashes_cache[k] = {}
                    self._hashes_cache[k][f] = v
            rows = self._execute("SELECT key, member, score FROM redis_zsets", fetch="all") or []
            with self._lock:
                for k, m, sc in rows:
                    if k not in self._zsets_cache:
                        self._zsets_cache[k] = {}
                    self._zsets_cache[k][m] = float(sc)
        except Exception:
            pass
    def _writer_loop(self):
        while True:
            try:
                task = self._writer_queue.get()
                if task is None:
                    break
                op = task[0]
                if op == "set":
                    _, key, val, exp = task
                    self._execute("""
                        INSERT INTO redis_kv (key, value, expires_at)
                        VALUES (%s, %s, %s)
                        ON CONFLICT (key) DO UPDATE
                        SET value = EXCLUDED.value,
                            expires_at = EXCLUDED.expires_at
                    """, (key, val, exp))
                elif op == "del":
                    _, keys = task
                    placeholders = ",".join(["%s"] * len(keys))
                    self._execute(f"DELETE FROM redis_kv WHERE key IN ({placeholders})", keys)
                    self._execute(f"DELETE FROM redis_sets WHERE key IN ({placeholders})", keys)
                    self._execute(f"DELETE FROM redis_hashes WHERE key IN ({placeholders})", keys)
                    self._execute(f"DELETE FROM redis_zsets WHERE key IN ({placeholders})", keys)
                elif op == "expire":
                    _, key, exp = task
                    self._execute("UPDATE redis_kv SET expires_at = %s WHERE key = %s", (exp, key))
                elif op == "sadd":
                    _, key, values = task
                    for val in values:
                        self._execute("""
                            INSERT INTO redis_sets (key, member)
                            VALUES (%s, %s)
                            ON CONFLICT (key, member) DO NOTHING
                        """, (key, val))
                elif op == "srem":
                    _, key, values = task
                    for val in values:
                        self._execute("DELETE FROM redis_sets WHERE key = %s AND member = %s", (key, val))
                elif op == "hset":
                    _, key, field, val = task
                    self._execute("""
                        INSERT INTO redis_hashes (key, field, value)
                        VALUES (%s, %s, %s)
                        ON CONFLICT (key, field) DO UPDATE
                        SET value = EXCLUDED.value
                    """, (key, field, val))
                elif op == "hdel":
                    _, key, fields = task
                    for f in fields:
                        self._execute("DELETE FROM redis_hashes WHERE key = %s AND field = %s", (key, f))
                elif op == "zadd":
                    _, key, mem, sc = task
                    self._execute("""
                        INSERT INTO redis_zsets (key, member, score)
                        VALUES (%s, %s, %s)
                        ON CONFLICT (key, member) DO UPDATE
                        SET score = EXCLUDED.score
                    """, (key, mem, sc))
                self._writer_queue.task_done()
            except Exception:
                pass
    def get(self, key):
        import time
        k = str(key)
        now = int(time.time())
        with self._lock:
            if k in self._kv_cache:
                val, exp = self._kv_cache[k]
                if exp is None or exp > now:
                    return val
                else:
                    del self._kv_cache[k]
                    self._writer_queue.put(("del", [k]))
                    return None
        return None
    def set(self, key, value, ex=None, px=None, nx=False, xx=False, **kwargs):
        import time
        k = str(key)
        v = str(value)
        now = int(time.time())
        expires_at = None
        if ex is not None:
            expires_at = now + int(ex)
        elif px is not None:
            expires_at = now + int(px // 1000)
        with self._lock:
            if nx and k in self._kv_cache:
                val, exp = self._kv_cache[k]
                if exp is None or exp > now:
                    return False
            if xx and k not in self._kv_cache:
                return False
            self._kv_cache[k] = (v, expires_at)
        self._writer_queue.put(("set", k, v, expires_at))
        return True
    def delete(self, *keys):
        if not keys:
            return 0
        str_keys = [str(k) for k in keys]
        cnt = 0
        with self._lock:
            for k in str_keys:
                if k in self._kv_cache:
                    del self._kv_cache[k]
                    cnt += 1
                if k in self._sets_cache:
                    del self._sets_cache[k]
                    cnt += 1
                if k in self._hashes_cache:
                    del self._hashes_cache[k]
                    cnt += 1
                if k in self._zsets_cache:
                    del self._zsets_cache[k]
                    cnt += 1
        if str_keys:
            self._writer_queue.put(("del", str_keys))
        return max(cnt, 1) if str_keys else 0
    def exists(self, *keys):
        if not keys:
            return 0
        import time
        str_keys = [str(k) for k in keys]
        now = int(time.time())
        cnt = 0
        with self._lock:
            for k in str_keys:
                if k in self._kv_cache:
                    _, exp = self._kv_cache[k]
                    if exp is None or exp > now:
                        cnt += 1
                elif k in self._sets_cache and self._sets_cache[k]:
                    cnt += 1
                elif k in self._hashes_cache and self._hashes_cache[k]:
                    cnt += 1
                elif k in self._zsets_cache and self._zsets_cache[k]:
                    cnt += 1
        return cnt
    def expire(self, key, time_secs):
        import time
        k = str(key)
        now = int(time.time())
        expires_at = now + int(time_secs)
        with self._lock:
            if k in self._kv_cache:
                val, _ = self._kv_cache[k]
                self._kv_cache[k] = (val, expires_at)
                self._writer_queue.put(("expire", k, expires_at))
                return True
        return False
    def ttl(self, key):
        import time
        k = str(key)
        now = int(time.time())
        with self._lock:
            if k in self._kv_cache:
                _, exp = self._kv_cache[k]
                if exp is None:
                    return -1
                rem = exp - now
                return rem if rem >= 0 else -2
        return -2
    def incr(self, key, amount=1):
        k = str(key)
        with self._lock:
            val_str, exp = self._kv_cache.get(k, ("0", None))
            val = int(val_str) if str(val_str).lstrip('-').isdigit() else 0
            val += int(amount)
            new_val_str = str(val)
            self._kv_cache[k] = (new_val_str, None)
        self._writer_queue.put(("set", k, new_val_str, None))
        return val
    def keys(self, pattern="*"):
        import fnmatch
        pat = str(pattern)
        with self._lock:
            all_keys = set(self._kv_cache.keys()) | set(self._sets_cache.keys()) | set(self._hashes_cache.keys()) | set(self._zsets_cache.keys())
        if pat == "*":
            return list(all_keys)
        return [k for k in all_keys if fnmatch.fnmatch(k, pat)]
    def smembers(self, key):
        k = str(key)
        with self._lock:
            return set(self._sets_cache.get(k, set()))
    def sadd(self, key, *values):
        if not values:
            return 0
        k = str(key)
        str_vals = [str(v) for v in values]
        added = 0
        with self._lock:
            if k not in self._sets_cache:
                self._sets_cache[k] = set()
            for v in str_vals:
                if v not in self._sets_cache[k]:
                    self._sets_cache[k].add(v)
                    added += 1
        if added > 0:
            self._writer_queue.put(("sadd", k, str_vals))
        return added
    def srem(self, key, *values):
        if not values:
            return 0
        k = str(key)
        str_vals = [str(v) for v in values]
        removed = 0
        with self._lock:
            if k in self._sets_cache:
                for v in str_vals:
                    if v in self._sets_cache[k]:
                        self._sets_cache[k].remove(v)
                        removed += 1
        if removed > 0:
            self._writer_queue.put(("srem", k, str_vals))
        return removed
    def sismember(self, key, value):
        k = str(key)
        v = str(value)
        with self._lock:
            return v in self._sets_cache.get(k, set())
    def hset(self, key, field=None, value=None, mapping=None):
        k = str(key)
        pairs = {}
        if mapping:
            pairs.update(mapping)
        if field is not None and value is not None:
            pairs[field] = value
        if not pairs:
            return 0
        added = 0
        with self._lock:
            if k not in self._hashes_cache:
                self._hashes_cache[k] = {}
            for f, v in pairs.items():
                sf, sv = str(f), str(v)
                self._hashes_cache[k][sf] = sv
                self._writer_queue.put(("hset", k, sf, sv))
                added += 1
        return added
    def hget(self, key, field):
        k = str(key)
        f = str(field)
        with self._lock:
            return self._hashes_cache.get(k, {}).get(f)
    def hgetall(self, key):
        k = str(key)
        with self._lock:
            return dict(self._hashes_cache.get(k, {}))
    def hdel(self, key, *fields):
        if not fields:
            return 0
        k = str(key)
        deleted = 0
        with self._lock:
            if k in self._hashes_cache:
                for f in fields:
                    sf = str(f)
                    if sf in self._hashes_cache[k]:
                        del self._hashes_cache[k][sf]
                        deleted += 1
        if deleted > 0:
            self._writer_queue.put(("hdel", k, [str(f) for f in fields]))
        return deleted
    def zadd(self, key, mapping):
        if not mapping:
            return 0
        k = str(key)
        added = 0
        with self._lock:
            if k not in self._zsets_cache:
                self._zsets_cache[k] = {}
            for mem, sc in mapping.items():
                sm, sc_float = str(mem), float(sc)
                self._zsets_cache[k][sm] = sc_float
                self._writer_queue.put(("zadd", k, sm, sc_float))
                added += 1
        return added
    def zrevrange(self, key, start, end, withscores=False):
        k = str(key)
        with self._lock:
            zset_items = list(self._zsets_cache.get(k, {}).items())
        zset_items.sort(key=lambda x: x[1], reverse=True)
        slice_items = zset_items[start:end+1] if end >= 0 else zset_items[start:]
        if withscores:
            return [(item[0], item[1]) for item in slice_items]
        return [item[0] for item in slice_items]
