def _command_gate(m, name):
    try:
        text = str(getattr(m, 'text', '') or '').strip()
        allowed = _COMMAND_GATES.get(name, ())
        if text in allowed:
            return True
        low = text.lower()
        # الأوامر التي قد تُكتب مع معرف البوت أو كصيغة /command.
        if low.startswith('/'):
            base = low.split('@', 1)[0]
            return base in {str(x).lower() for x in allowed}
        # أوامر البحث/الكشف ذات وسيط واحد.
        if name == 'get_my_rank':
            return low.startswith(('كشف ', 'ايدي ', 'id ', 'رتبتي '))
        return False
    except Exception:
        return True

