def _bot_perm_key(cid, uid, action):
    return f"{cid}:botperm:{uid}:{action}:{hmshelp}"

def _bot_perm_value(cid, uid, action):
    value = r.get(_bot_perm_key(cid, uid, action))
    if value is None:
        return None
    if isinstance(value, bytes):
        value = value.decode("utf-8", "ignore")
    return str(value).strip().lower() not in ("0", "false", "no", "off", "")

def bot_action_allowed(uid, cid, action):
    # المالك/المطورين لا تتغير صلاحياتهم بهذا الجدول.
    if gowner_pls(uid, cid) or owner_pls(uid, cid) or dev_pls(uid, cid):
        return True
    explicit = _bot_perm_value(cid, uid, action)
    if explicit is not None:
        return explicit
    # المدير يسمح له افتراضياً، الادمن والمميز ممنوعين حتى يفعّل المالك الصلاحية.
    if r.get(f"{cid}:rankMOD:{uid}{hmshelp}"):
        return True
    return False

def _bot_perm_markup(cid, target_id):
    rows = []
    for action, label in _BOT_RANK_PERMISSIONS.items():
        allowed = bot_action_allowed(target_id, cid, action)
        rows.append([
            create_emoji_btn(
                f"{'🟢' if allowed else '🔴'} {label}",
                callback_data=f"botperm_{action}_{target_id}",
                color="success" if allowed else "danger",
            )
        ])
    rows.append([create_emoji_btn("إغلاق", callback_data=f"botperm_close_{target_id}", color="danger")])
    return InlineKeyboardMarkup(rows)

def _bot_perm_target_rank(cid, uid):
    return bool(
        r.get(f"{cid}:rankGOWNER:{uid}{hmshelp}") or
        r.get(f"{cid}:rankOWNER:{uid}{hmshelp}") or
        r.get(f"{cid}:rankMOD:{uid}{hmshelp}") or
        r.get(f"{cid}:rankADMIN:{uid}{hmshelp}") or
        r.get(f"{cid}:rankPRE:{uid}{hmshelp}")
    )

