# ===== نظام التاك المخصص =====
# الاستخدام: اكتب "اضف تاك" ثم أرسل الاسم، وبعدها أرسل @username.
# بعدها أي شخص يكتب الاسم بالضبط، البوت يرد عليه بتاك لليوزر المحفوظ
# مع جملة عراقية عشوائية. هذا المسار عالي الأولوية حتى لا يتأثر بالحماية.
_TAG_SETUP_PREFIX = "tag_setup"
_TAG_RANDOM_REPLIES = [
    "شكو نايم؟ 😂",
    "وينك يمعود؟",
    "هاا شبيك مختفي؟ 😅",
    "يمعود قوم من النوم 😂",
    "شعندك ساكت؟",
    "تعال شوفهم شمسوين 😂",
    "وين رايح؟",
    "ها حلوة نومته؟ 😴",
]

def _tag_setup_key(cid, uid):
    return f"{cid}:{_TAG_SETUP_PREFIX}:{uid}:{hmshelp}"

def _tag_name_key(cid, name):
    return f"{cid}:custom_tag:{name.strip().lower()}:{hmshelp}"

def _tag_decode(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", "ignore")
    return str(value) if value is not None else ""

@app.on_message(filters.text & filters.group, group=-1000000000001)
def customTagFast(c, m):
    try:
        text = (getattr(m, "text", None) or "").strip()
        cid = int(m.chat.id)
        uid = int(m.from_user.id)
        setup_key = _tag_setup_key(cid, uid)
        setup = _tag_decode(r.get(setup_key))

        # بدء الإضافة.
        if text == "اضف تاك":
            if not mod_pls(uid, cid):
                return m.reply("غير مسموح لك بهذا الأمر")
            r.set(setup_key, "name", ex=300)
            return m.reply("-︰ارسل الاسم الآن .")

        # إلغاء الإضافة.
        if setup and text == "الغاء":
            r.delete(setup_key)
            return m.reply("-︰تم إلغاء إضافة التاك .")

        # الخطوة الأولى: حفظ الاسم.
        if setup == "name":
            if not text or len(text) > 50:
                return m.reply("-︰ارسل اسم صحيح وقصير .")
            r.set(setup_key, "username", ex=300)
            r.set(f"{setup_key}:name", text, ex=300)
            return m.reply("-︰ارسل اليوزر الآن مثل @username .")

        # الخطوة الثانية: حفظ اليوزر مع الاسم.
        if setup == "username":
            username = text.strip().split()[0] if text.strip() else ""
            username = username.lstrip("@")
            if not re.fullmatch(r"[A-Za-z0-9_]{5,32}", username):
                return m.reply("-︰اليوزر غير صحيح، ارسله مثل @username .")
            name = _tag_decode(r.get(f"{setup_key}:name")).strip()
            if not name:
                r.delete(setup_key)
                r.delete(f"{setup_key}:name")
                return m.reply("-︰انتهت جلسة الإضافة، اكتب اضف تاك من جديد .")
            r.set(_tag_name_key(cid, name), username, ex=0)
            r.delete(setup_key)
            r.delete(f"{setup_key}:name")
            return m.reply(f"-︰تم حفظ التاك بنجاح\n-︰الاسم: {name}\n-︰اليوزر: @{username}")

        # التاك يعمل بالاسم المطابق حرفياً، ولا نسمح له بالتدخل بكلمة "ها".
        if text and text not in _CASUAL_REPLIES:
            username = _tag_decode(r.get(_tag_name_key(cid, text))).strip()
            if username:
                phrase = random.choice(_TAG_RANDOM_REPLIES)
                return m.reply(f"@{username} {phrase}", quote=True)
    except Exception as e:
        print(f"CUSTOM_TAG_ERROR: {e!r}")

# ===== الرد الفوري عند مناداة البوت باسمه =====
# هذا المسار مستقل وعالي الأولوية حتى لا تبتلع معالجات الحماية/الفلاتر اسم البوت.
@app.on_message(filters.text & filters.group, group=-2000000000000000000)
def _instant_bot_name_reply(c, m):
    try:
        raw = str(getattr(m, "text", "") or "").strip()
        if not raw:
            return
        bot_name = str(get_bot_name() or "").strip()
        if not bot_name:
            return
        # إزالة التطويل والتشكيل حتى يعمل الاسم حتى لو كتبه العضو بشكل مزخرف بسيط.
        norm_raw = re.sub(r"[\u064b-\u065f\u0670\u0640\u200b-\u200f\ufeff]", "", raw)
        norm_name = re.sub(r"[\u064b-\u065f\u0670\u0640\u200b-\u200f\ufeff]", "", bot_name)
        if norm_raw != norm_name:
            return
        replies = [
            f"{bot_name} موجود، شتريد؟",
            "أحب من تناديني باسمي ❤️",
            f"أنا {bot_name}، شلون أساعدك؟",
            f"لك شبيك كل شوي تناديني {bot_name} 😂",
            f"{bot_name} يمك هسه"
        ]
        m.reply(text=f"<b>{html.escape(random.choice(replies))}</b>", parse_mode=ParseMode.HTML)
        try:
            m.stop_propagation()
        except Exception:
            pass
    except Exception as e:
        print(f"INSTANT_BOT_NAME_ERROR: {e!r}")

# ===== ردود الكلمات اليومية =====
# هذا المسار يأتي قبل الحماية حتى لا تُحذف كلمة "ها" أو تُعامل كأمر حماية.
_CASUAL_REPLIES = {
    "ها": ["ها يول شبيك يمعود؟ 😂", "ها حبيبي شتريد؟", "ها شكو ماكو؟ 😅", "هاا شبيك؟"],
    "هلا": ["هلا وغلا 😎", "هلا يمعود", "هلا حبيبي شكو؟", "هلااا شلونك؟"],
    "هلو": ["هلوو 😄", "هلو حبيبي", "هلو شكو؟", "هلو يمعود"],
    "يول": ["يول شتريد؟ 😂", "ها يول شبيك؟", "يول يمعود شكو؟", "هاا يول"],
    "يمعود": ["ها يمعود شبيك؟ 😂", "يمعود شتريد؟", "هلا يمعود", "شكو يمعود؟"],
}

@app.on_message(filters.text & filters.group, group=-1000000000000)
def casualWordsFast(c, m):
    try:
        text = (getattr(m, "text", None) or "").strip()
        # لا نتدخل إلا بالكلمات المحددة حرفياً.
        replies = _CASUAL_REPLIES.get(text)
        if not replies:
            return
        m.reply(random.choice(replies))
        try:
            m.stop_propagation()
        except Exception:
            pass
    except Exception as e:
        print(f"CASUAL_REPLY_ERROR: {e!r}")

@app .on_message (filters .group ,group =-1111111111111 )
async def on_zbi (c :Client ,m :Message ):
    name =get_bot_name()
    text =m .text
    if text .startswith (f"{name } "):
        text =text .replace (f"{name } ","")
    if r .get (f"{m .chat .id }:Custom:{m .chat .id }{hmshelp }&text={text }"):
        text =r .get (f"{m .chat .id }:Custom:{m .chat .id }{hmshelp }&text={text }")
    if r .get (f"Custom:{hmshelp }&text={text }"):
        text =r .get (f"Custom:{hmshelp }&text={text }")
    if r .get (f"inDontCheck:{hmshelp }"):
        return m .continue_propagation ()
    if dev_pls (m .from_user .id ,m .chat .id ):
        return
    if (
    text .startswith ("تفعيل ")
    or text .startswith ("تعطيل ")
    or text .startswith ("قفل ")
    or text .startswith ("فتح ")
    or text =="ايدي"
    or text =="الاوامر"
    ):
        if r .get (f"forceChannel:{hmshelp }")and (
        not r .get (f"disableSubscribe:{hmshelp }")
        ):
            username =r .get (f"forceChannel:{hmshelp }").replace ("@","")
            not_member =False
            try :
                member =await c .get_chat_member (username ,m .from_user .id )
            except FloodWait :
                return m .continue_propagation ()
            except UserNotParticipant :
                await m .reply (
                f"- انضم للقناة ( @{username } ) لتستطيع استخدام اوامر البوت",
                reply_markup =InlineKeyboardMarkup (
                [
                [
                create_emoji_btn (
                "اضغط هنا",url ="https://t.me/"+username
                )
                ]
                ]
                ),
                )
                r .set (f"inDontCheck:{hmshelp }",1 ,ex =10 )
                return m .stop_propagation ()
            except Exception as e :
                print (e )
                return m .continue_propagation ()
            if member .status in {
            enums .ChatMemberStatus .LEFT ,
            enums .ChatMemberStatus .BANNED ,
            }or member .status is None :
                not_member =True
            else :
                not_member =False
            if not_member :
                await m .reply (
                f"- انضم للقناة ( @{username } ) لتستطيع استخدام اوامر البوت",
                reply_markup =InlineKeyboardMarkup (
                [
                [
                create_emoji_btn (
                "اضغط هنا",url ="https://t.me/"+username
                )
                ]
                ]
                ),
                )
                r .set (f"inDontCheck:{hmshelp }",ex =10 )
                return m .stop_propagation ()
            else :
                return m .continue_propagation ()
