def _is_tashweesh_text(text):
    """كشف تشويش فعّال: رموز، تكرار حروف، تطويل، محارف خفية، وأغلب الرسالة رموز."""
    if not text:
        return False
    try:
        t = str(text).strip()
        if len(t) < 3:
            return False
        if re.search(r'[\u200B-\u200F\u202A-\u202E\u2060-\u2064\u2066-\u206F\uFEFF]', t):
            return True
        if re.search(r'ـ{3,}', t):
            return True
        # كشف الحركات المتراكمة والرموز الخفية داخل الكلمات المشوشة
        marks = sum(1 for ch in t if unicodedata.category(ch).startswith('M'))
        if marks >= 3 and marks / max(len(t), 1) >= 0.15:
            return True
        compact = ''.join(ch for ch in unicodedata.normalize('NFKC', t)
                          if not unicodedata.category(ch).startswith('M')
                          and ch not in '\u200b\u200c\u200d\u200e\u200f\ufeff')
        compact_letters = re.sub(r'[\W_]+', '', compact, flags=re.UNICODE)
        # الكلمات التي تفصل حروفها بعلامات/مسافات كثيرة أو تكرر مقاطعها
        if len(compact_letters) >= 4 and len(compact) >= 6 and len(compact_letters) / len(compact) >= 0.35:
            if re.search(r'(.)\1{4,}', compact_letters) or re.search(r'(.{1,3})\1{2,}', compact_letters):
                return True
        if re.search(r'([!@#$%^&*()_+=\[\]{};:\'"\\|,.<>?/~`\-])\1{2,}', t):
            return True
        if re.search(r'(.)\1{5,}', t, re.DOTALL):
            return True
        if re.search(r'(.{1,4})\1{2,}', t, re.DOTALL):
            return True
        symbols = len(re.findall(r'[^\w\s\u0600-\u06FF]', t, re.UNICODE))
        letters = len(re.findall(r'[A-Za-z\u0600-\u06FF]', t, re.UNICODE))
        if len(t) >= 5 and symbols >= 4 and symbols / max(len(t), 1) >= 0.45 and letters <= 2:
            return True
        if re.search(r'([\W_])\1{3,}', t, re.UNICODE):
            return True
        return False
    except Exception as e:
        print(f"TASHWEEESH_DETECT_ERROR: {e}")
        return False

def _tashweesh_guard_worker(c, m):
    try:
        if not r.get(f"{m.chat.id}:lockTashweesh:{hmshelp}"):
            return
        if not getattr(m, "from_user", None):
            return
        # الادمن وفوق مستثنون من القفل.
        if pre_pls(m.from_user.id, m.chat.id):
            return
        payload = getattr(m, "text", None) or getattr(m, "caption", None)
        if _is_tashweesh_text(payload):
            try:
                m.delete()
            except Exception as delete_error:
                try:
                    c.delete_messages(m.chat.id, m.id)
                except Exception:
                    print(f"TASHWEEESH_DELETE_ERROR: {delete_error}")
    except Exception as e:
        print(f"TASHWEEESH_GUARD_ERROR: {e}")

# مسار مستقل وفوري للتشويش.
# لا يستخدم طابوراً أو ThreadPool حتى يتم حذف رسالة التشويش فور وصولها.
@app .on_message (filters .group, group=-1000)
def tashweeshTextGuard(c, m):
    try:
        if not r.get(f"{m.chat.id}:lockTashweesh:{hmshelp}"):
            return
        if not getattr(m, "from_user", None):
            return
        # الادمن وفوق مستثنون من القفل.
        if pre_pls(m.from_user.id, m.chat.id):
            return
        payload = getattr(m, "text", None) or getattr(m, "caption", None)
        if _is_tashweesh_text(payload):
            try:
                # حذف مباشر، مع مسار احتياطي إذا تعذر الحذف من كائن الرسالة.
                m.delete()
            except Exception as delete_error:
                try:
                    c.delete_messages(m.chat.id, m.id)
                except Exception as fallback_error:
                    print(f"TASHWEEESH_DELETE_ERROR: {delete_error}; fallback: {fallback_error}")
    except Exception as e:
        print(f"TASHWEEESH_GUARD_ERROR: {e}")

