# ===== أوامر صوره / متحركه / انطق =====
_RANDOM_ANIM_CACHE = {}
_RANDOM_ANIM_LOCK = threading.Lock()
_RANDOM_ANIM_MAX = 30


def _remember_random_animation(c, m):
    try:
        anim = getattr(m, 'animation', None)
        if not anim:
            return
        fid = getattr(anim, 'file_id', None)
        if not fid:
            return
        cid = int(m.chat.id)
        with _RANDOM_ANIM_LOCK:
            pool = _RANDOM_ANIM_CACHE.setdefault(cid, [])
            if fid in pool:
                return
            pool.append(fid)
            if len(pool) > _RANDOM_ANIM_MAX:
                del pool[:-_RANDOM_ANIM_MAX]
    except Exception as e:
        print('RANDOM_ANIM_CACHE_ERROR:', e)


@app.on_message(filters.animation, group=27)
def rememberAnimationsHandler(c, m):
    _remember_random_animation(c, m)


