def _pick_unique_media(pool, recent_map, cid, max_recent=5):
    cid = int(cid)
    with threading.Lock():
        recent = recent_map.setdefault(cid, [])
        available = [x for x in pool if x not in recent]
        if not available:
            available = list(pool)
            recent.clear()
        item = random.choice(available)
        recent.append(item)
        if len(recent) > max_recent:
            del recent[:-max_recent]
        return item


def _send_random_photo(c, m):
    """يرسل صورة بورتريه/رومانسية حقيقية عشوائية بدل كارت الاقتباس."""
    cid = int(m.chat.id)
    try:
        url = _pick_unique_media(_QUOTE_PHOTO_URLS, _QUOTE_PHOTO_RECENT, cid, 6)
        # Telegram/Pyrogram يقدر يجلب الصورة من الرابط مباشرة، فلا نحتاج ملفات مؤقتة.
        return c.send_photo(cid, url, caption='@FD_CQ', reply_to_message_id=m.id)
    except Exception as e:
        print('QUOTE_PHOTO_URL_ERROR:', repr(e))
        try:
            # احتياط إذا Telegram رفض الرابط: ننزله ونرسله كملف.
            rr = requests.get(url, timeout=20, headers={'User-Agent': 'Mozilla/5.0'})
            rr.raise_for_status()
            bio = BytesIO(rr.content)
            bio.name = 'photo.jpg'
            return c.send_photo(cid, bio, caption='@FD_CQ', reply_to_message_id=m.id)
        except Exception as e2:
            print('QUOTE_PHOTO_DOWNLOAD_ERROR:', repr(e2))
            return m.reply('تعذر تجهيز الصورة حالياً، جرّب الأمر مرة ثانية.')


