def _ensure_edge_tts():
    """تجهيز Edge TTS إذا المكتبة مو مثبتة."""
    try:
        import edge_tts
        return edge_tts
    except Exception:
        try:
            subprocess.run(
                [sys.executable, '-m', 'pip', 'install', '-q', '--disable-pip-version-check', 'edge-tts'],
                check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=90
            )
            import edge_tts
            return edge_tts
        except Exception as e:
            print('EDGE_TTS_INSTALL_ERROR:', repr(e))
            return None


def _edge_tts_save(text, output_file, voice='ar-IQ-BasselNeural'):
    """توليد صوت عراقي عصبي Neural من Microsoft Edge TTS."""
    edge_tts = _ensure_edge_tts()
    if edge_tts is None:
        raise RuntimeError('edge-tts غير متوفر')

    async def _make():
        # BasselNeural هو صوت عراقي ذكوري رسمي، ونخليه أهدأ وأقرب للكلام الطبيعي.
        communicate = edge_tts.Communicate(
            text,
            voice,
            rate='-3%',
            volume='+0%',
            pitch='-1Hz',
        )
        await communicate.save(output_file)

    # ما نفترض وجود event loop حتى لو البوت شغال داخل loop.
    error = [None]
    def runner():
        try:
            asyncio.run(_make())
        except Exception as e:
            error[0] = e
    th = Thread(target=runner, daemon=True)
    th.start()
    th.join(75)
    if th.is_alive():
        raise TimeoutError('Edge TTS timed out')
    if error[0] is not None:
        raise error[0]
    if not os.path.exists(output_file) or os.path.getsize(output_file) < 1000:
        raise RuntimeError('Edge TTS returned empty audio')


def _send_say_voice(c, m, txt):
    """انطق: صوت عراقي طبيعي Neural، مع Google TTS كاحتياط إذا Edge TTS تعطل."""
    txt = str(txt or '').strip()
    if not txt:
        return m.reply('اكتب النص بعد انطق أو انطقي.')
    if len(txt) > 500:
        return m.reply('توكل مايمدي انطق اكثر من ٥٠٠ حرف بتعب بعدين')

    work = tempfile.mkdtemp(prefix='bot_say_')
    try:
        mp3 = os.path.join(work, 'speech.mp3')
        edge_error = None
        try:
            # الصوت الأساسي: باسل، صوت Neural رسمي بلهجة العراق.
            _edge_tts_save(txt, mp3, 'ar-IQ-BasselNeural')
        except Exception as e:
            edge_error = e
            print('EDGE_TTS_BASSEL_ERROR:', repr(e))

        # احتياط عراقي فقط: رنا أيضاً صوت Neural عراقي، حتى ما نرجع لصوت عربي غير عراقي.
        if not os.path.exists(mp3) or os.path.getsize(mp3) < 1000:
            try:
                _edge_tts_save(txt, mp3, 'ar-IQ-RanaNeural')
            except Exception as e:
                edge_error = e
                print('EDGE_TTS_RANA_ERROR:', repr(e))

        if not os.path.exists(mp3) or os.path.getsize(mp3) < 1000:
            raise RuntimeError(f'لم يصل صوت عراقي من Edge TTS: {edge_error!r}')

        ogg = os.path.join(work, 'speech.ogg')
        ffmpeg = shutil.which('ffmpeg') or 'ffmpeg'
        subprocess.run([
            ffmpeg, '-y', '-i', mp3, '-map', '0:a:0', '-vn',
            '-c:a', 'libopus', '-b:a', '48k', '-ar', '48000',
            '-application', 'voip', ogg
        ], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30)

        return m.reply_voice(ogg, caption='@FD_CQ')
    except Exception as e:
        print('SAY_VOICE_ERROR:', repr(e))
        return m.reply(f'تعذر نطق النص حالياً: {e}')
    finally:
        shutil.rmtree(work, ignore_errors=True)

