@app.on_callback_query(filters.regex(r"^cleanup:"), group=0)
def cleanupCallbackFast(c, m):
    """معالج مباشر لأزرار التنظيف؛ لا يدخل ThreadPool حتى لا تظهر الأزرار كأنها وهمية."""
    try:
        try: m.answer()
        except Exception: pass
        uid = int(getattr(getattr(m, 'from_user', None), 'id', 0) or 0)
        msg = getattr(m, 'message', None)
        cid = int(getattr(getattr(msg, 'chat', None), 'id', 0) or 0)
        if not (admin_pls(uid, cid) or pre_pls(uid, cid) or _cleanup_is_admin(msg)):
            try: m.answer('هذا الأمر يخص ( المدير وفوق ) بس', show_alert=True)
            except Exception: pass
            return
        data = str(getattr(m, 'data', '') or '')
        parts = data.split(':')
        action = parts[1] if len(parts) > 1 else ''
        value = parts[2] if len(parts) > 2 else ''

        if action == 'toggle' and value:
            state = not bool(_cleanup_get(cid, value))
            _cleanup_set(cid, value, state)
            # عند تشغيل أي نوع من التنظيف المؤقت، فعّل المفتاح الرئيسي تلقائياً.
            if state and value in ('photos','videos','stickers','gifs','audio','voice','documents','video_notes','any_media'):
                _cleanup_set(cid, 'auto_clean_enabled', True)
            return msg.edit_reply_markup(reply_markup=_cleanup_keyboard(cid))

        if action == 'any_media':
            state = not bool(_cleanup_get(cid, 'any_media'))
            _cleanup_set(cid, 'any_media', state)
            if state:
                _cleanup_set(cid, 'auto_clean_enabled', True)
            return msg.edit_reply_markup(reply_markup=_cleanup_keyboard(cid))

        if action in ('timeminus','timeplus','timeminus5','timeplus5','timeminus1','timeplus1'):
            cur = int(_cleanup_get(cid, 'auto_clean_time') or 5)
            if action in ('timeminus5','timeminus'):
                cur -= 300
            elif action in ('timeplus5','timeplus'):
                cur += 300
            elif action == 'timeminus1':
                cur -= 60
            elif action == 'timeplus1':
                cur += 60
            cur = max(5, min(86400, cur))
            _cleanup_set(cid, 'auto_clean_time', cur)
            return msg.edit_reply_markup(reply_markup=_cleanup_keyboard(cid))

        if action == 'time':
            return msg.edit_text('<b>المسح التلقائي</b>\nاختر مدة المسح من الأزرار:', reply_markup=_cleanup_keyboard(cid), parse_mode=ParseMode.HTML)

        if action == 'auto':
            enabled = bool(_cleanup_get(cid, 'auto_clean_enabled'))
            if enabled:
                _cleanup_set(cid, 'auto_clean_enabled', False)
            else:
                _cleanup_set(cid, 'auto_clean_enabled', True)
                if not _cleanup_get(cid, 'auto_clean_time'):
                    _cleanup_set(cid, 'auto_clean_time', 5)
            return msg.edit_reply_markup(reply_markup=_cleanup_keyboard(cid))

        if action == 'usertype':
            new_type = 'all' if _cleanup_get(cid, 'user_type') != 'all' else 'normal'
            _cleanup_set(cid, 'user_type', new_type)
            label = 'الكل' if new_type == 'all' else 'عادي'
            try: m.answer(f'تم تغيير نوع المستخدم إلى: {label}', show_alert=False)
            except Exception: pass
            return msg.edit_reply_markup(reply_markup=_cleanup_keyboard(cid))

        if action == 'back':
            return msg.delete()
    except Exception as e:
        print('CLEANUP_CALLBACK_ERROR:', repr(e))
        try: m.answer('صار خطأ بالزر، جرب مرة ثانية.', show_alert=True)
        except Exception: pass

@app .on_callback_query (group =1 )
def CallbackQueryHandler (c ,m ):
    # نفحص زر الأوامر أولاً: لا answer ولا Redis ولا ThreadPool قبل تعديل الرسالة.
    # هذا يجعل ظهور صفحة الأوامر أسرع ما يمكن.
    _cb_data = str(getattr(m, "data", "") or "")
    if _cb_data.startswith("commands") or _cb_data.startswith("panel:"):
        # هذه الأزرار لها معالج أولوية مستقل. لا تعالجها هنا مرة ثانية.
        return
        # لا ننتظر answer() لأنه طلب شبكة مستقل؛ شغله بالخلفية حتى يبدأ
        # تعديل لوحة الأوامر فوراً بدون طلبين متتاليين.
        try:
            FAST_REPLY_EXECUTOR.submit(lambda: m.answer())
        except Exception:
            pass
        try:
            CallbackQueryResponse(c, m, "")
        except Exception as _fast_cb_err:
            print("FAST_COMMAND_BUTTON_ERROR:", repr(_fast_cb_err))
        try:
            m.stop_propagation()
        except Exception:
            pass
        return
    # لا ننتظر answer()؛ إرسال تأكيد الضغط بالخلفية حتى تبدأ معالجة الزر فوراً.
    try:
        FAST_REPLY_EXECUTOR.submit(lambda: m.answer())
    except Exception:
        pass

    if _cb_data == "devpanel:verify":
        return _force_sub_verify(c, m)

    if _cb_data.startswith("devpanel"):
        try:
            chat_id = getattr(getattr(m, "message", None), "chat", None)
            chat_id = getattr(chat_id, "id", m.from_user.id)
            if not dev_pls(m.from_user.id, chat_id):
                return m.answer("هذا الزر للمطور فقط", show_alert=True)
        except Exception:
            return m.answer("هذا الزر للمطور فقط", show_alert=True)
        if _cb_data == "devpanel:open":
            markup = InlineKeyboardMarkup([
                [create_emoji_btn("تغيير صورة البداية", callback_data="devpanel:photo")],
                [create_emoji_btn("تغيير اسم البوت", callback_data="devpanel:name")],
                [create_emoji_btn("الاشتراك الإجباري", callback_data="devpanel:force")],
                [create_emoji_btn("إغلاق لوحة التحكم", callback_data="devpanel:close")],
            ])
            return m.message.edit_text("لوحة التحكم\n\nاختر الإعداد الذي تريد تغييره:", reply_markup=markup)
        if _cb_data == "devpanel:photo":
            r.set(f"{hmshelp}:panel_wait_photo:{m.from_user.id}", 1, ex=900)
            try:
                START_PHOTO_WAITING.add(int(m.from_user.id))
            except Exception:
                pass
            return m.message.edit_text("🖼 أرسل الآن صورة واحدة فقط.\n\nبعد إرسالها تصبح هي صورة /start مباشرة.", reply_markup=InlineKeyboardMarkup([[create_emoji_btn("رجوع", callback_data="devpanel:open")]]))
        if _cb_data == "devpanel:name":
            r.set(f"{hmshelp}:panel_wait_name:{m.from_user.id}", 1, ex=900)
            return m.message.edit_text("✏️ أرسل الآن اسم البوت الجديد.\n\nسيظهر الاسم الجديد في رسالة /start مباشرة.", reply_markup=InlineKeyboardMarkup([[create_emoji_btn("رجوع", callback_data="devpanel:open")]]))
        if _cb_data == "devpanel:force":
            enabled = bool(r.get(f"{hmshelp}:force_sub_enabled"))
            channel = r.get(f"{hmshelp}:force_sub_channel") or "غير محددة"
            status = "مفعل ✅" if enabled else "معطل ❌"
            markup = InlineKeyboardMarkup([
                [create_emoji_btn("تعيين قناة الاشتراك", callback_data="devpanel:force_set")],
                [create_emoji_btn("تفعيل الاشتراك", callback_data="devpanel:force_on"), create_emoji_btn("تعطيل الاشتراك", callback_data="devpanel:force_off")],
                [create_emoji_btn("رجوع", callback_data="devpanel:open")],
            ])
            return m.message.edit_text(f"الاشتراك الإجباري\n\nالحالة: {status}\nالقناة: {channel}\n\nلازم تكون القناة عامة ويكون البوت موجوداً فيها حتى يقدر يتحقق من الاشتراك.", reply_markup=markup)
        if _cb_data == "devpanel:force_set":
            r.set(f"{hmshelp}:panel_wait_channel:{m.from_user.id}", 1)
            return m.message.edit_text("أرسل يوزر قناة الاشتراك مثل:\n@MyChannel\n\nلا ترسل رابطاً، أرسل اليوزر فقط.", reply_markup=InlineKeyboardMarkup([[create_emoji_btn("رجوع", callback_data="devpanel:force")]]))
        if _cb_data == "devpanel:force_on":
            if not r.get(f"{hmshelp}:force_sub_channel"):
                return m.answer("عيّن قناة الاشتراك أولاً", show_alert=True)
            r.set(f"{hmshelp}:force_sub_enabled", 1)
            return m.message.edit_text("تم تفعيل الاشتراك الإجباري ✅", reply_markup=InlineKeyboardMarkup([[create_emoji_btn("رجوع", callback_data="devpanel:force")]]))
        if _cb_data == "devpanel:force_off":
            r.delete(f"{hmshelp}:force_sub_enabled")
            return m.message.edit_text("تم تعطيل الاشتراك الإجباري ✅", reply_markup=InlineKeyboardMarkup([[create_emoji_btn("رجوع", callback_data="devpanel:force")]]))
        if _cb_data == "devpanel:close":
            return m.message.delete()
        return
    channel =(
    r .get (f"{hmshelp }:BotChannel")if r .get (f"{hmshelp }:BotChannel")else "FD_CQ"
    )
    # أزرار صفحات الأوامر خفيفة جداً (مجرد تعديل رسالة)، لذلك ننفذها
    # مباشرة داخل callback handler ولا نضعها خلف أي طابور/مهام أخرى.
    # هذا يلغي التأخير الذي يظهر عند الضغط على م1/م2/م3/الألعاب/التسلية/البنك/زواج.
    try:
        CALLBACK_EXECUTOR.submit(CallbackQueryResponse ,c ,m ,channel )
    except Exception:
        BOT_EXECUTOR.submit(CallbackQueryResponse ,c ,m ,channel )


