@app.on_message(filters.group, group=-9999999999999999)
def cleanupGuard(c,m):
    try:
        # في وضع "عادي" نتجاهل رسائل المشرفين، وفي وضع "الكل" تدخل رسائلهم أيضاً.
        if _cleanup_get(m.chat.id, 'user_type') != 'all' and _cleanup_is_admin(m): return
        # أمر فتح اللوحة لا يدخل في الحذف.
        txt=(getattr(m,'text',None) or '').strip()
        if txt in ('التنظيف','تنظيف'): return
        # المسار المباشر للوسائط: يمنع مرور الصور/الفيديوهات/الفيديو الدائري
        # عندما يكون خيار "أي رسالة غير نصية" مفعلاً.
        cid = int(getattr(getattr(m, 'chat', None), 'id', 0) or 0)
        if _cleanup_should_delete(m):
            _cleanup_schedule_or_delete(c,m)
    except Exception as e:
        print(f'CLEANUP_GUARD_ERROR: {e}')

# أمر التنظيف مستقل وفوري؛ يمنع أي معالج لاحق من ابتلاعه أو تحويله لأمر آخر.
@app.on_message(filters.group, group=-9999999999999)
def cleanupCommandFast(c,m):
    # مسار مستقل بأولوية أعلى من جميع معالجات الحماية والردود.
    # لا نعتمد على filters.text حتى لا تضيع الرسالة بسبب اختلاف نسخة Pyrogram
    # أو وجود entities/captions في الرسالة.
    try:
        raw = getattr(m, 'text', None) or ''
        txt = str(raw).replace('ـ','').strip()
        txt = re.sub(r'[\u064b-\u065f\u0670\u200b-\u200f\ufeff]', '', txt)
        normalized = re.sub(r'\s+', '', txt)
        if normalized not in ('التنظيف','تنظيف'):
            return

        uid = getattr(getattr(m, 'from_user', None), 'id', 0) or 0
        cid = getattr(getattr(m, 'chat', None), 'id', 0) or 0
        if not (admin_pls(uid, cid) or _cleanup_is_admin(m)):
            try:
                m.reply('هذا الأمر يخص ( المدير وفوق ) بس')
            except Exception:
                pass
            try: m.stop_propagation()
            except Exception: pass
            return

        # نستخدم أزرار Pyrogram العادية هنا لضمان ظهور اللوحة حتى مع
        # إصدارات Pyrogram التي لا تدعم ButtonStyle الحديث.
        try:
            markup = _cleanup_keyboard(cid)
        except Exception as kb_err:
            print('CLEANUP_KEYBOARD_ERROR:', repr(kb_err))
            markup = InlineKeyboardMarkup([
                [InlineKeyboardButton('وسائط مؤقتة', callback_data='cleanup:auto')],
                [InlineKeyboardButton('أي رسالة غير نصية', callback_data='cleanup:any_media')],
                [InlineKeyboardButton('ملصق', callback_data='cleanup:toggle:stickers'), InlineKeyboardButton('الصورة المتحركة', callback_data='cleanup:toggle:gifs')],
                [InlineKeyboardButton('الصورة', callback_data='cleanup:toggle:photos'), InlineKeyboardButton('الفيديو', callback_data='cleanup:toggle:videos')],
                [InlineKeyboardButton('الموسيقى', callback_data='cleanup:toggle:audio'), InlineKeyboardButton('الملف', callback_data='cleanup:toggle:documents')],
                [InlineKeyboardButton('وقت حذف الوسائط 5 ثواني', callback_data='cleanup:time')],
                [InlineKeyboardButton('‹', callback_data='cleanup:timeminus'), InlineKeyboardButton('›', callback_data='cleanup:timeplus')],
                [InlineKeyboardButton('نوع المستخدم المستخدم عادي', callback_data='cleanup:usertype')],
                [InlineKeyboardButton('رجوع ◄', callback_data='cleanup:back')],
            ])

        try:
            sent = m.reply_text(_cleanup_panel_text(), reply_markup=markup, parse_mode=ParseMode.HTML)
        except Exception:
            sent = m.reply(_cleanup_panel_text(), reply_markup=markup)
        try:
            r.set(f"{hmshelp}:cleanup_panel:{cid}:{sent.id}", uid, ex=86400)
        except Exception:
            pass
        try: m.stop_propagation()
        except Exception: pass
    except Exception as e:
        print(f'CLEANUP_COMMAND_FAST_ERROR: {e}')

