def _panel_key(cid, key): return f"{cid}:{key}:{hmshelp}"

# نفس مفاتيح Redis التي تعتمد عليها أوامر قفل/فتح الأصلية.
_PANEL_ALL_LOCK_KEYS = (
    "lockJoin", "lockChannels", "lockEdit", "lockEditM", "lockVoice",
    "lockVideo", "lockNot", "lockPhoto", "lockStickers", "lockAnimations",
    "lockFiles", "lockPersian", "lockUrls", "lockHashtags", "lockMessages",
    "lockTags", "lockBots", "lockSpam", "lockInline", "lockForward",
    "lockAudios", "lockaddContacts", "lockSHTM", "lockKFR", "lockNSFW", "lockTashweesh", "mute"
)

def _panel_mget(cid, keys):
    try:
        vals = r.mget([_panel_key(cid,k) for k in keys])
        return {k: bool(v) for k,v in zip(keys, vals)}
    except Exception:
        return {k: bool(r.get(_panel_key(cid,k))) for k in keys}

def _panel_enabled(cid, key, mode):
    if mode == "absent": return not bool(r.get(_panel_key(cid,key)))
    if mode == "present": return bool(r.get(_panel_key(cid,key)))
    if mode == "special":
        states = _panel_mget(cid, _PANEL_PROTECTION_KEYS)
        return all(states.get(k, False) for k in _PANEL_PROTECTION_KEYS)
    return False

