def _panel_enable_markup(cid, uid):
    rows=[]; row=[]
    # قراءة الحالة دفعة واحدة حتى لا يتأخر فتح الصفحة بسبب عشرات طلبات Redis.
    keys=[key for _,key,mode,_ in _PANEL_ENABLE_ITEMS if mode != "special"]
    states=_panel_mget(cid, keys)
    for i,(label,key,mode,perm) in enumerate(_PANEL_ENABLE_ITEMS):
        if mode == "absent": active=not states.get(key,False)
        elif mode == "present": active=states.get(key,False)
        elif mode == "special": active=all(states.get(x,False) for x in _PANEL_PROTECTION_KEYS)
        else: active=False
        row.append(create_emoji_btn(("🟢 " if active else "🔴 ")+label,callback_data=f"panel:e:{i}",color="success" if active else "danger"))
        if len(row)==2: rows.append(row); row=[]
    if row: rows.append(row)
    rows.append([create_emoji_btn("↩️ رجوع للوحة الرئيسية",callback_data=f"panel:back:{uid}",color="primary")])
    return InlineKeyboardMarkup(rows)

def _panel_lock_markup(cid, uid):
    rows=[]; row=[]
    states=_panel_mget(cid, _PANEL_ALL_LOCK_KEYS)
    for i,(label,key) in enumerate(_PANEL_LOCK_ITEMS):
        active=(all(states.get(k,False) for k in _PANEL_ALL_LOCK_KEYS) if key=="__all__" else states.get(key,False))
        row.append(create_emoji_btn(("🔴 " if active else "🟢 ")+label,callback_data=f"panel:l:{i}",color="danger" if active else "success"))
        if len(row)==2: rows.append(row); row=[]
    if row: rows.append(row)
    rows.append([create_emoji_btn("↩️ رجوع للوحة الرئيسية",callback_data=f"panel:back:{uid}",color="primary")])
    return InlineKeyboardMarkup(rows)

def _panel_set(cid, key, enabled):
    full=_panel_key(cid,key)
    if enabled: r.set(full,1)
    else: r.delete(full)

def _panel_toggle_protection(cid, enable):
    try:
        pipe=r.pipeline(transaction=False)
        for key in _PANEL_PROTECTION_KEYS:
            if enable: pipe.set(_panel_key(cid,key),1)
            else: pipe.delete(_panel_key(cid,key))
        if enable: pipe.delete(_panel_key(cid,"disableWarn"))
        pipe.execute()
    except Exception:
        for key in _PANEL_PROTECTION_KEYS: _panel_set(cid,key,enable)
        if enable: r.delete(_panel_key(cid,"disableWarn"))

def _panel_toggle_all(cid, lock):
    try:
        pipe=r.pipeline(transaction=False)
        for key in _PANEL_ALL_LOCK_KEYS:
            if lock: pipe.set(_panel_key(cid,key),1)
            else: pipe.delete(_panel_key(cid,key))
        pipe.execute()
    except Exception:
        for key in _PANEL_ALL_LOCK_KEYS: _panel_set(cid,key,lock)


_COMMAND_ACTIVE_PAGE = {}
_COMMAND_ACTIVE_LOCK = threading.Lock()

def _set_command_active_page(uid, data):
    try:
        page = str(data or "").split(":", 1)[0]
        if page.startswith("commands"):
            with _COMMAND_ACTIVE_LOCK:
                _COMMAND_ACTIVE_PAGE[int(uid)] = page
    except Exception:
        pass

def _command_nav_markup(markup, uid):
    """أزرار صفحات الأوامر: الأخضر افتراضياً، والزر المضغوط فقط أحمر."""
    try:
        with _COMMAND_ACTIVE_LOCK:
            active_page = _COMMAND_ACTIVE_PAGE.get(int(uid), "")
        rows = [list(row) for row in (getattr(markup, "inline_keyboard", None) or [])]
        page_labels = {
            'م1': 'commands1', 'م2': 'commands2', 'م3': 'commands3',
            'الالعاب': 'commands4', 'التسليه': 'commands5',
            'البنك': 'commands7', 'زواج': 'commands8',
            'التفعيل والتعطيل': 'commands9', 'القفل والفتح': 'commands10',
        }
        styled = []
        for row in rows:
            new_row = []
            for btn in row:
                label = str(getattr(btn, "text", "") or "")
                data = str(getattr(btn, "callback_data", "") or "")
                clean_label = label.replace('‣', '').replace('›', '').strip()
                page = data.split(":", 1)[0] if data.startswith("commands") else page_labels.get(clean_label, "")
                if page in page_labels.values():
                    current = bool(active_page and page == active_page)
                    new_row.append(create_emoji_btn(label, callback_data=data, color=('danger' if current else 'success')))
                else:
                    new_row.append(btn)
            styled.append(new_row)
        rows = [row for row in styled if not any(
            str(getattr(btn, "callback_data", "") or "") in (
                f"commands9:{uid}", f"commands10:{uid}"
            )
            for btn in row
        )]
        rows.append([
            create_emoji_btn("التفعيل والتعطيل", callback_data=f"commands9:{uid}", color=('danger' if active_page == 'commands9' else 'success')),
            create_emoji_btn("القفل والفتح", callback_data=f"commands10:{uid}", color=('danger' if active_page == 'commands10' else 'success')),
        ])
        rows.append([create_emoji_btn("مشاعر", url="https://t.me/FD_CQ", color="primary")])
        return InlineKeyboardMarkup(rows)
    except Exception as e:
        print("COMMAND_NAV_MARKUP_ERROR:", repr(e))
        return InlineKeyboardMarkup([
            [create_emoji_btn("م1", callback_data=f"commands1:{uid}", color=('danger' if active_page == 'commands1' else 'success')),
             create_emoji_btn("م2", callback_data=f"commands2:{uid}", color=('danger' if active_page == 'commands2' else 'success'))],
            [create_emoji_btn("م3", callback_data=f"commands3:{uid}", color=('danger' if active_page == 'commands3' else 'success'))],
            [create_emoji_btn("الالعاب", callback_data=f"commands4:{uid}", color=('danger' if active_page == 'commands4' else 'success')),
             create_emoji_btn("التسليه", callback_data=f"commands5:{uid}", color=('danger' if active_page == 'commands5' else 'success'))],
            [create_emoji_btn("البنك", callback_data=f"commands7:{uid}", color=('danger' if active_page == 'commands7' else 'success'))],
            [create_emoji_btn("التفعيل والتعطيل", callback_data=f"commands9:{uid}", color=('danger' if active_page == 'commands9' else 'success')),
             create_emoji_btn("القفل والفتح", callback_data=f"commands10:{uid}", color=('danger' if active_page == 'commands10' else 'success'))],
            [create_emoji_btn("مشاعر", url="https://t.me/FD_CQ", color="primary")],
        ])

def CallbackQueryResponse (c ,m ,channel ):
    _cb_data = str(getattr(m,"data","") or "")
    # حفظ آخر زر أوامر ضغطه المستخدم حتى يبقى هو الأحمر عند إعادة بناء الكيبورد.
    try:
        if _cb_data.startswith("commands"):
            _set_command_active_page(getattr(m.from_user, "id", 0), _cb_data)
    except Exception:
        pass
    _cb_data = str(getattr(m,"data","") or "")
    if _cb_data.startswith("panel:"):
        # callback مباشر: لا Executor ولا انتظار طابور.
        parts=_cb_data.split(":")
        action=parts[1] if len(parts)>1 else ""
        value=parts[2] if len(parts)>2 else ""
        uid=int(getattr(m.from_user,"id",0) or 0)
        cid=int(getattr(getattr(m.message,"chat",None),"id",0) or 0)
        if action=="back":
            with _COMMAND_ACTIVE_LOCK:
                _COMMAND_ACTIVE_PAGE.pop(int(uid), None)
            return m.edit_message_text(_commands_panel_text(),reply_markup=_command_nav_markup(_panel_main_markup(uid),uid))
        if action=="e":
            try: m.answer()
            except Exception: pass
            try: i=int(value)
            except Exception: return
            if not (0 <= i < len(_PANEL_ENABLE_ITEMS)): return
            label,key,mode,perm=_PANEL_ENABLE_ITEMS[i]
            allowed=(perm=="owner" and owner_pls(uid,cid)) or (perm=="admin" and admin_pls(uid,cid)) or (perm=="mod" and mod_pls(uid,cid))
            if not allowed:
                return m.answer("هذا الامر يخص ( المدير وفوق ) بس",show_alert=True)
            active=_panel_enabled(cid,key,mode)
            if key=="__protection__":
                _panel_toggle_protection(cid,not active)
            else:
                _panel_set(cid,key,not active)
            return m.edit_message_reply_markup(reply_markup=_panel_enable_markup(cid,uid))
        if action=="l":
            try: m.answer()
            except Exception: pass
            try: i=int(value)
            except Exception: return
            if not (0 <= i < len(_PANEL_LOCK_ITEMS)): return
            label,key=_PANEL_LOCK_ITEMS[i]
            if not mod_pls(uid,cid):
                return m.answer("هذا الامر يخص ( المدير وفوق ) بس",show_alert=True)
            if key=="__all__":
                states=_panel_mget(cid,_PANEL_ALL_LOCK_KEYS)
                active=all(states.values())
                _panel_toggle_all(cid,not active)
            else:
                _panel_set(cid,key,not bool(r.get(_panel_key(cid,key))))
            return m.edit_message_reply_markup(reply_markup=_panel_lock_markup(cid,uid))
        return

    # صفحات الأوامر لا تحتاج botkey؛ جلبه من Redis كان يضيف تأخيراً غير ضروري.
    _cb_data = str(getattr(m, "data", "") or "")
    if _cb_data.startswith("commands") or _cb_data.startswith("panel:"):
        k = ""
    else:
        k =r .get (f"{hmshelp }:botkey")

