def delcommand (c ,m ,k ):
   if not r .get (f'{m .chat .id }:enable:{hmshelp }'): r.set(f'{m.chat.id}:enable:{hmshelp}', 1)
   if r .get (f'{m .from_user .id }:mute:{m .chat .id }{hmshelp }'):return
   if r .get (f'{m .from_user .id }:mute:{hmshelp }'):return
   if r .get (f'{m .chat .id }:mute:{hmshelp }')and not admin_pls (m .from_user .id ,m .chat .id ):return
   if r .get (f'{m .chat .id }addCustomG:{m .from_user .id }{hmshelp }'):return
   text =m .text
   if r .get (f'{m .chat .id }:Custom:{m .chat .id }{hmshelp }&text={m .text }'):
       text =r .get (f'{m .chat .id }:Custom:{m .chat .id }{hmshelp }&text={m .text }')
   if r .get (f'Custom:{hmshelp }&text={m .text }'):
       text =r .get (f'Custom:{hmshelp }&text={m .text }')
   if isLockCommand (m .from_user .id ,m .chat .id ,text ):return
   if r .get (f'{m .chat .id }:delCustom:{m .from_user .id }{hmshelp }')and text =='الغاء':
     r .delete (f'{m .chat .id }:delCustom:{m .from_user .id }{hmshelp }')
     return m .reply (quote =True ,text =f'{k } من عيوني لغيت مسح امر ')
   if text =='مسح الاوامر'or text =='مسح الاوامر المضافة':
     if not mod_pls (m .from_user .id ,m .chat .id ):
       return m .reply (quote =True ,text =f'{k } هذا الامر يخص ( المدير وفوق ) وبس')
     else :
       if not r .smembers (f'{m .chat .id }:listCustom:{m .chat .id }{hmshelp }'):
         return m .reply (quote =True ,text =f'{k } مافيه اوامر مضافه')
       else :
         count =0
         for cmnd in r .smembers (f'{m .chat .id }:listCustom:{m .chat .id }{hmshelp }'):
           command =cmnd
           r .delete (f'{m .chat .id }:Custom:{m .chat .id }{hmshelp }&text={command }')
           r .srem (f'{m .chat .id }:listCustom:{m .chat .id }{hmshelp }',command )
           count +=1
         text =f'من「 {m .from_user .mention } 」\n{k } ابشر مسحت {count } أمر\n☆'
         return m .reply (quote =True ,text =text )
   if text =='مسح امر':
     if not r .get (f'{m .chat .id }:delCustom:{m .from_user .id }{hmshelp }'):
       if not mod_pls (m .from_user .id ,m .chat .id ):
          return m .reply (quote =True ,text =f'{k } هذا الامر يخص ( المدير وفوق ) وبس')
       else :
          r .set (f'{m .chat .id }:delCustom:{m .from_user .id }{hmshelp }',1 )
          m .reply (quote =True ,text =f'{k } ارسل الامر الحين')
          return
   if r .get (f'{m .chat .id }:delCustom:{m .from_user .id }{hmshelp }')and admin_pls (m .from_user .id ,m .chat .id )and len (m .text )<50 :
      r .delete (f'{m .chat .id }:delCustom:{m .from_user .id }{hmshelp }')
      if not r .get (f'{m .chat .id }:Custom:{m .chat .id }{hmshelp }&text={m .text }'):
         return m .reply (quote =True ,text =f'{k } هذا الأمر مو مضاف')
      r .srem (f'{m .chat .id }:listCustom:{m .chat .id }{hmshelp }',m .text )
      r .delete (f'{m .chat .id }:Custom:{m .chat .id }{hmshelp }&text={m .text }')
      m .reply (quote =True ,text =f'{k } من「 {m .from_user .mention } 」\n{k } ابشر مسحت الأمر\n☆')
      return
