@app.on_message(filters.group, group=9)
def addmsgCount(c, m):
    _cid = m.chat.id
    _uid = m.from_user.id if m.from_user else 0
    _fname = m.from_user.first_name[:25] if m.from_user else ""
    def _do():
        try:
            if r.get(f'{_uid}:mute:{_cid}{hmshelp}'): return
            key = f'{hmshelp}{_cid}:TotalMsgs:{_uid}'
            cur = r.get(key)
            r.set(key, (int(cur) + 1) if cur else 1)
            r.set(f"{_uid}:bankName", _fname)
        except Exception: pass
    defer(_do)
