@app.on_message((filters.photo | filters.document) & filters.private, group=-100)
def developer_start_photo_handler(c,m):
   global START_DEV_PHOTO_ID, START_PHOTO_WAITING
   # هذا handler مخصص لصورة لوحة التحكم، ويعمل قبل بقية handlers الخاصة
   # بالخاص حتى لا تلتقطه معالجات أخرى أولاً. يدعم الصورة العادية والصورة
   # المرسلة كملف أيضاً.
   try:
      if not getattr(m, 'from_user', None):
         return
      uid = int(m.from_user.id)
      key = f"{hmshelp}:panel_wait_photo:{uid}"
      waiting = False
      try:
         waiting = bool(r.get(key))
      except Exception as _redis_read_error:
         print('START_PHOTO_WAIT_READ_ERROR:', repr(_redis_read_error))
      try:
         waiting = waiting or (uid in START_PHOTO_WAITING)
      except Exception:
         pass

      if not waiting:
         return

      # file_id للصورة العادية، أو للملف إذا أرسلها المستخدم كـ document.
      photo_id = None
      photo_obj = getattr(m, 'photo', None)
      if photo_obj:
         photo_id = getattr(photo_obj, 'file_id', None)
      if not photo_id:
         document_obj = getattr(m, 'document', None)
         if document_obj:
            mime = str(getattr(document_obj, 'mime_type', '') or '')
            if mime.startswith('image/'):
               photo_id = getattr(document_obj, 'file_id', None)
      if not photo_id:
         try:
            m.reply(text='⚠️ أرسل صورة بصيغة صورة أو ملف صورة فقط.', quote=True)
         except Exception:
            pass
         return

      photo_id = str(photo_id)

      # الحفظ الفعلي: /start سيقرأ start_photo مباشرة من Redis.
      START_DEV_PHOTO_ID = photo_id
      r.set(f"{hmshelp}:start_photo", photo_id)
      r.set(f"{hmshelp}:start_dev_photo", photo_id)

      try:
         r.delete(key)
      except Exception:
         pass
      try:
         START_PHOTO_WAITING.discard(uid)
      except Exception:
         pass

      # نرسل تأكيداً واضحاً بعد الحفظ، ثم معاينة الصورة.
      try:
         m.reply_photo(
            photo=photo_id,
            caption='✅ تم حفظ صورة البداية بنجاح\n\n🖼 ستظهر هذه الصورة الآن مع /start.',
            quote=True
         )
      except Exception as preview_error:
         print('START_PHOTO_PREVIEW_ERROR:', repr(preview_error))
         try:
            m.reply(text='✅ تم حفظ صورة البداية بنجاح\nلكن تعذر إرسال المعاينة. أرسل /start للتأكد.', quote=True)
         except Exception:
            pass
   except Exception as e:
      print('START_PHOTO_PANEL_ERROR:', repr(e))
      try:
         m.reply(text='⚠️ صار خطأ أثناء حفظ الصورة. اضغط «تغيير صورة البداية» وحاول مرة ثانية.', quote=True)
      except Exception:
         pass

@app .on_message (filters .text &filters .private ,group =1 )
def private_delRanksHandler (c ,m ):
    # /start له أولوية مطلقة: لا نعتبره اسم قناة أو اسم بوت حتى لو كانت
    # هناك حالة انتظار مفتوحة من لوحة التحكم. هذا يمنع ظهور رسالة
    # "القناة غير صحيحة" عند الضغط على /start أثناء إعداد الاشتراك.
    if m.text and dev_pls(m.from_user.id, m.chat.id):
        # إعداد اسم البوت من لوحة التحكم
        wait_name_key=f"{hmshelp}:panel_wait_name:{m.from_user.id}"
        if r.get(wait_name_key):
            new_name=m.text.strip()
            if not new_name or len(new_name)>80:
                return m.reply(text='اسم البوت غير صالح. أرسل اسماً من 1 إلى 80 حرفاً.', quote=True)
            r.set(f"{hmshelp}:BotName", new_name)
            r.delete(wait_name_key)
            return m.reply(text=f"تم تغيير اسم البوت إلى: {new_name} ✅\nجرّب /start الآن.", quote=True)

        wait_channel_key=f"{hmshelp}:panel_wait_channel:{m.from_user.id}"
        if r.get(wait_channel_key):
            channel=m.text.strip()
            channel=channel.replace('https://t.me/','').replace('http://t.me/','').strip('/')
            if channel.startswith('joinchat/') or channel.startswith('+'):
                return m.reply(text='أرسل يوزر قناة عامة مثل @MyChannel حتى أقدر أتحقق من الاشتراك.', quote=True)
            if not channel.startswith('@'): channel='@'+channel
            # تحقق فعلي من القناة قبل حفظها.
            try:
                c.get_chat(channel)
            except Exception as e:
                return m.reply(text='القناة غير صحيحة أو البوت لا يستطيع الوصول لها.\nتأكد أن القناة عامة والبوت موجود فيها ثم أرسل اليوزر مرة ثانية.', quote=True)
            r.set(f"{hmshelp}:force_sub_channel", channel)
            r.delete(wait_channel_key)
            return m.reply(text=f"تم تعيين قناة الاشتراك: {channel} ✅\nالآن ارجع للوحة وفعل الاشتراك الإجباري.",quote=True)
    k =r .get (f'{hmshelp }:botkey')
    PRIVATE_EXECUTOR.submit(private_func ,c ,m ,k )
