START_DEV_PHOTO_ID = None
START_PHOTO_WAITING = set()
START_DEV_PHOTO_LOCK = __import__('threading').Lock()

# /start المباشر: يمنع معالجات الخاص الأخرى من تأخير أول تشغيل.
# يطابق /start فقط، لذلك /start sarhni وباقي روابط البداية تبقى كما هي.
@app.on_message(filters.regex(r"^/start(?:@[A-Za-z0-9_]+)?$") & filters.private, group=-3000)
def _instant_start_handler(c, m):
   try:
      fast_start_handler(c, m)
   except Exception as e:
      print('INSTANT_START_ERROR:', repr(e))
      try:
         # مسار احتياطي بسيط جداً إذا فشل مسار البداية السريع.
         name = get_bot_name()
         m.reply(
            text=f"• أهلاً بك عزيزي\n• أنا بوت اسمي {name}\n• اختصاص البوت حماية المجموعات",
            quote=True
         )
      except Exception as e2:
         print('INSTANT_START_FALLBACK_ERROR:', repr(e2))
   try:
      raise StopPropagation
   except TypeError:
      return


def _force_sub_channel_url(channel):
   ch=str(channel or '').strip()
   if ch.startswith('@'): return 'https://t.me/' + ch[1:]
   if ch.startswith('https://t.me/'): return ch
   if ch and not ch.startswith('-'): return 'https://t.me/' + ch
   return None

def _force_sub_is_member(c, user_id):
   # المطور لا يخضع للاشتراك الإجباري.
   try:
      uid = int(user_id)
      bot_owner = int(r.get(f'{hmshelp}botowner') or 0)
      if uid in {1920665874, int(owner_id), bot_owner}:
         return True
   except Exception:
      pass
   channel = r.get(f'{hmshelp}:force_sub_channel')
   if isinstance(channel, bytes):
      try: channel = channel.decode('utf-8')
      except Exception: channel = str(channel)
   if not channel: return True
   try:
      member = c.get_chat_member(channel, int(user_id))
      status = getattr(member, 'status', None)
      status_name = str(getattr(status, 'name', status)).upper()
      if status_name in ('LEFT', 'KICKED', 'BANNED'): return False
      if status_name == 'RESTRICTED' and getattr(member, 'is_member', True) is False: return False
      return True
   except Exception as e:
      # إذا القناة غير صحيحة أو البوت لا يستطيع فحصها، لا نعتبر المستخدم مشتركاً.
      # هذا يمنع تجاوز الاشتراك الإجباري بسبب خطأ في الفحص.
      print('FORCE_SUB_CHECK_ERROR:', repr(e))
      return False

def _force_sub_verify(c, query):
   if not _force_sub_is_member(c, query.from_user.id):
      try: query.answer('لسه ما اشتركت بالقناة', show_alert=True)
      except Exception: pass
      return
   try: query.answer('تم التحقق من الاشتراك ✅')
   except Exception: pass
   try: query.message.delete()
   except Exception: pass
   name=get_bot_name()
   text=f"""• أهلاً بك عزيزي
• أنا بوت اسمي {name}
• اختصاص البوت حماية المجموعات
• أفضل بوت حماية والعاب وحصريات 🎖️
• اضف البوت الى مجموعتك .
• ارفع البوت مشرف ويتفعل تلقائياً .
• مطور البوت ↤︎"""
   rows=[
      [create_emoji_btn('قناة البوت',url='https://t.me/FD_CQ'), create_emoji_btn('اضفني لمجموعتك',url=f'https://t.me/{botUsername}?startgroup=Commands&admin=ban_users+restrict_members+delete_messages+add_admins+change_info+invite_users+pin_messages+manage_call+manage_chat+manage_video_chats+promote_members')],
      [create_emoji_btn('المطور',url='https://t.me/u_8_y'), create_emoji_btn('تنصيب البوت',url='https://t.me/u_8_y')],
      [create_emoji_btn('مشاعر',url='https://t.me/FD_CQ')],
   ]
   if dev_pls(query.from_user.id, query.message.chat.id):
      rows.append([create_emoji_btn('لوحة التحكم',callback_data='devpanel:open')])
   markup=InlineKeyboardMarkup(rows)
   # إذا وضع المطور صورة مخصصة، استخدمها حصراً ولا تستبدلها بصورة المطور القديمة.
   photo_id=r.get(f'{hmshelp}:start_photo')
   if not photo_id:
      photo_id=START_DEV_PHOTO_ID
   if isinstance(photo_id, bytes):
      try: photo_id = photo_id.decode('utf-8')
      except Exception: photo_id = str(photo_id)
   try:
      if photo_id: c.send_photo(query.message.chat.id, photo_id, caption=text, reply_markup=markup)
      else: c.send_message(query.message.chat.id, text, reply_markup=markup)
   except Exception as e:
      print('FORCE_SUB_START_SEND_ERROR:',repr(e))

def _force_sub_gate(c, m):
   if not r.get(f'{hmshelp}:force_sub_enabled'): return False
   # المطور/المالك مستثنى دائماً من الاشتراك الإجباري، حتى لو فشل فحص القناة.
   try:
      uid = int(m.from_user.id)
      bot_owner = int(r.get(f'{hmshelp}botowner') or 0)
      if uid in {1920665874, int(owner_id), bot_owner} or dev_pls(uid, m.chat.id):
         return False
   except Exception:
      pass
   if _force_sub_is_member(c, m.from_user.id): return False
   channel = r.get(f'{hmshelp}:force_sub_channel')
   if isinstance(channel, bytes):
      try: channel = channel.decode('utf-8')
      except Exception: channel = str(channel)
   rows=[]
   url=_force_sub_channel_url(channel)
   if url: rows.append([create_emoji_btn('الاشتراك بالقناة', url=url)])
   rows.append([create_emoji_btn('تحقق من الاشتراك', callback_data='devpanel:verify')])
   m.reply(text='لازم تشترك بالقناة أولاً حتى تستخدم البوت.', reply_markup=InlineKeyboardMarkup(rows), quote=True)
   return True

