def _live_group_owner(c, cid):
    """جلب مالك المجموعة الحالي من قائمة المشرفين، وعدم الاعتماد على كاش قديم."""
    try:
        for mm in c.get_chat_members(int(cid), filter=ChatMembersFilter.ADMINISTRATORS):
            if getattr(mm, "status", None) == ChatMemberStatus.OWNER:
                owner = getattr(mm, "user", None)
                if owner is not None:
                    try:
                        full_owner = c.get_users(int(owner.id))
                        if full_owner is not None:
                            owner = full_owner
                    except Exception:
                        pass
                    try:
                        _cache_owner_profile(int(cid), owner)
                    except Exception:
                        pass
                    return owner
    except Exception as e:
        print("LIVE_OWNER_LOOKUP_ERROR:", repr(e))
    return None

def _get_real_group_owner(c, cid):
    """جلب مالك المجموعة الحالي من تيليجرام، وعدم الاعتماد على كاش قديم."""
    try:
        for mm in c.get_chat_members(int(cid), filter=ChatMembersFilter.ADMINISTRATORS):
            if mm.status == ChatMemberStatus.OWNER:
                return mm.user
    except Exception as e:
        print("REAL_GROUP_OWNER_ERROR:", repr(e))
    return None

def _welcome_owner_id(c, cid):
    try:
        owner = _get_real_group_owner(c, cid)
        if owner is not None:
            return int(owner.id)
    except Exception:
        pass
    return None

_WELCOME_DEFAULT_B64 = """"""
_WELCOME_DEFAULT_PATH = None
_WELCOME_DEFAULT_LOCK = threading.Lock()

def _welcome_default_photo():
    global _WELCOME_DEFAULT_PATH
    try:
        if _WELCOME_DEFAULT_PATH and os.path.exists(_WELCOME_DEFAULT_PATH):
            return _WELCOME_DEFAULT_PATH
        with _WELCOME_DEFAULT_LOCK:
            if _WELCOME_DEFAULT_PATH and os.path.exists(_WELCOME_DEFAULT_PATH):
                return _WELCOME_DEFAULT_PATH
            path = os.path.join(tempfile.gettempdir(), "bbott_welcome_default.jpg")
            if not os.path.exists(path):
                with open(path, "wb") as f:
                    f.write(base64.b64decode(_WELCOME_DEFAULT_B64))
            _WELCOME_DEFAULT_PATH = path
            return path
    except Exception as e:
        print("WELCOME_DEFAULT_PHOTO_ERROR:", repr(e))
        return None

def _welcome_markup(c, cid):
    """زر المالك حسب مالك المجموعة الحالي، وليس المطور أو كاش قديم."""
    try:
        owner = _get_real_group_owner(c, cid)
    except Exception:
        owner = None
    if owner is None:
        return None
    owner_id = int(owner.id)
    owner_name = str(getattr(owner, "first_name", None) or "المالك")
    owner_username = str(getattr(owner, "username", None) or "").lstrip("@")
    # نخزن المالك الصحيح للمجموعة فقط بعد التأكد منه من Telegram.
    _cache_owner_profile(cid, owner)
    try:
        return InlineKeyboardMarkup([[create_emoji_btn(
            f"@{owner_username}" if owner_username else owner_name,
            user_id=owner_id,
            color="primary"
        )]])
    except Exception as e:
        print("WELCOME_OWNER_BUTTON_ERROR:", repr(e))
        return None

@app .on_message (filters .group & filters .photo, group =28 )
def setWelcomePhotoHandler(c, m):
    try:
        caption = str(getattr(m, "caption", "") or "").strip()
        pending = r.get(f"{m.chat.id}:setWelcomePhoto:{m.from_user.id}{hmshelp}")
        direct = caption in ("وضع صورة الترحيب", "ضع صورة الترحيب")
        if not pending and not direct:
            return
        if not mod_pls(m.from_user.id, m.chat.id):
            return m.reply(f"{r.get(f'{hmshelp}:botkey')} هذا الامر يخص ( المدير وفوق ) بس")
        file_id = getattr(getattr(m, "photo", None), "file_id", None)
        if not file_id:
            return m.reply(f"{r.get(f'{hmshelp}:botkey')} ارسل صورة مو ملف")
        r.set(f"{m.chat.id}:CustomWelcomePhoto:{hmshelp}", file_id)
        r.delete(f"{m.chat.id}:setWelcomePhoto:{m.from_user.id}{hmshelp}")
        return m.reply(f"{r.get(f'{hmshelp}:botkey')} تم حفظ صورة الترحيب")
    except Exception as e:
        print("WELCOME_PHOTO_SET_ERROR:", repr(e))

@app .on_message (filters .group & filters .text ,group =29 )
def setWelcomeHandler (c ,m ):
    _cid = m.chat.id
    _uid = m.from_user.id
    _pending_rules = r.get(f"{_cid}:setRules:{_uid}{hmshelp}")
    _pending_welcome = r.get(f"{_cid}:setWelcome:{_uid}{hmshelp}")
    _pending_photo = r.get(f"{_cid}:setWelcomePhoto:{_uid}{hmshelp}")
    if not (_pending_rules or _pending_welcome or _pending_photo) and not _command_gate(m, 'welcomeFunc'):
        return
    k =r .get (f"{hmshelp }:botkey")
    BOT_EXECUTOR.submit(welcomeFunc ,c ,m ,k )

def welcomeFunc (c ,m ,k ):
    if not r .get (f"{m .chat .id }:enable:{hmshelp }"):
        r.set(f"{m.chat.id}:enable:{hmshelp}", 1)
    if r .get (f"{m .chat .id }:mute:{hmshelp }") and not admin_pls(m .from_user .id ,m .chat .id):
        return
    if r .get (f"{m .from_user .id }:mute:{m .chat .id }{hmshelp }") or r .get (f"{m .from_user .id }:mute:{hmshelp }"):
        return
    if r .get (f"{m .chat .id }:addCustom:{m .from_user .id }{hmshelp }") or r .get (f"{m .chat .id }addCustomG:{m .from_user .id }{hmshelp }"):
        return
    text = m.text
    name = get_bot_name()
    if text.startswith(f"{name} "):
        text = text.replace(f"{name} ", "", 1)
    if r.get(f"{m.chat.id}:Custom:{m.chat.id}{hmshelp}&text={text}"):
        text = r.get(f"{m.chat.id}:Custom:{m.chat.id}{hmshelp}&text={text}")
    if r.get(f"Custom:{hmshelp}&text={text}"):
        text = r.get(f"Custom:{hmshelp}&text={text}")
    if isLockCommand(m.from_user.id, m.chat.id, text):
        return
    if text == "الغاء" and r.get(f"{m.chat.id}:setWelcome:{m.from_user.id}{hmshelp}"):
        r.delete(f"{m.chat.id}:setWelcome:{m.from_user.id}{hmshelp}")
