@app.on_callback_query(filters.regex(r"^fast_owner_open:(\d+)$"), group=-1000000000000000004)
async def _fast_owner_open(c, q):
    try:
        owner_id = int(q.data.split(":", 1)[1])
        owner = c.get_users(owner_id)
        username = str(getattr(owner, "username", None) or "").lstrip("@")
        if username:
            await q.answer(url=f"https://t.me/{username}", cache_time=0)
        else:
            await q.answer(url=f"tg://user?id={owner_id}", cache_time=0)
    except Exception as e:
        print("FAST_OWNER_OPEN_ERROR:", repr(e))
        try:
            await q.answer("تعذر فتح حساب المالك", show_alert=True, cache_time=0)
        except Exception:
            pass

