@app .on_message (filters .new_chat_members ,group =4 )
def welcomeRespons (c :Client ,m :Message ):
    if not r.get(f"{m.chat.id}:enable:{hmshelp}"):
        r.set(f"{m.chat.id}:enable:{hmshelp}", 1)
    if r.get(f"{m.chat.id}:disableWelcome:{hmshelp}") or not m.new_chat_members:
        return
    welcome = r.get(f"{m.chat.id}:CustomWelcome:{hmshelp}") or "هلا ولله بـ {الاسم} ❤️🍭"
    custom_photo = r.get(f"{m.chat.id}:CustomWelcomePhoto:{hmshelp}")
    markup = _welcome_markup(c, m.chat.id)
    for me in m.new_chat_members:
        if me.id == int(hmshelp):
            continue
        if r.get(f"{m.chat.id}:enableVerify:{hmshelp}") and not pre_pls(me.id, m.chat.id):
            return
        title = m.chat.title or "المجموعة"
        name = me.first_name or "العضو"
        username = f"@{me.username}" if me.username else "بدون يوزر"
        # {المنشن} يذكر العضو مباشرة بالضغط عليه، حتى لو ما عنده يوزر.
        mention = f'<a href="tg://user?id={int(me.id)}">{html.escape(str(name))}</a>'
        TIME_ZONE = "Asia/Riyadh"
        ZONE = pytz.timezone(TIME_ZONE)
        TIME = datetime.now(ZONE)
        clock = TIME.strftime("%I:%M %p")
        date = TIME.strftime("%d/%m/%Y")
        rules = r.get(f"{m.chat.id}:CustomRules:{hmshelp}") or "{k} ممنوع نشر الروابط\n{k} ممنوع السب والشتم\n{k} ممنوع التوجيه\n{k} الرجاء احترام المدراء والادمنية"
        w = (welcome.replace("{القوانين}", rules).replace("{المنشن}", mention)
             .replace("{الاسم}", html.escape(str(name))).replace("{المجموعه}", html.escape(str(title)))
             .replace("{الوقت}", clock).replace("{التاريخ}", date)
             .replace("{اليوزر}", html.escape(str(username)))
             .replace("{k}", str(r.get(f"{hmshelp}:botkey") or "")))
        if r.get(f"{m.chat.id}:disableWelcomep:{hmshelp}"):
            # الصورة معطلة: أرسل نفس الترحيب كنص مع زر المالك.
            try:
                m.reply(w, disable_web_page_preview=True, reply_markup=markup)
            except Exception:
                c.send_message(m.chat.id, w, disable_web_page_preview=True, reply_markup=markup)
            continue
        photo = custom_photo or _welcome_default_photo()
        try:
            if photo:
                m.reply_photo(photo, caption=w, reply_markup=markup)
            else:
                m.reply(w, disable_web_page_preview=True, reply_markup=markup)
        except Exception as e:
            print("WELCOME_SEND_ERROR:", repr(e))
            try:
                m.reply(w, disable_web_page_preview=True, reply_markup=markup)
            except Exception:
                pass

import string
def get_id ():
   rndm =''.join ([random .choice (string .ascii_letters
   +string .digits )for n in range (7 )])
   return rndm
